{"code": "
const res = await tools.pwsh({ description: "Copy olean and clean probes", command: `Copy-Item .lake/build/lib/lean/tmp/sheaf/xif/paper/S1858GlobalTraceActual.olean tmp/sheaf/xif/paper/S1858GlobalTraceActual.olean -Force
Remove-Item tmp/sheaf/xif/paper/_S1858Probe*.lean, tmp/sheaf/xif/paper/_s1858_part*.lean -Force -ErrorAction SilentlyContinue
Get-ChildItem tmp/sheaf/xif/paper/ -Filter 'S1858*' | Select-Object Name,Length,LastWriteTime | Format-Table -AutoSize
Get-FileHash tmp/sheaf/xif/paper/S1858GlobalTraceActual.lean -Algorithm SHA256 | Select-Object -ExpandProperty Hash
Get-FileHash .lake/build/lib/lean/tmp/sheaf/xif/paper/S1858GlobalTraceActual.olean -Algorithm SHA256 | Select-Object -ExpandProperty Hash
Select-String -Path tmp/sheaf/xif/paper/S1858GlobalTraceActual.lean -Pattern 'sorry|admit|axiom |Shrink|ULift|PUnit' | Select-Object LineNumber,Line`, workdir: "D:\\lean", timeoutMs: 300000 });
console.log(res.kind === "foreground" ? "EXIT=" + res.exitCode + "\n" + res.stdout.text + res.stderr.text : JSON.stringify(res));
", "description": "Copy olean, clean probes, check for sorry"}

